use crate::io::AsyncWrite;

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io::{self, IoSlice};
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAllBuf<'a, W, B> {
        writer: &'a mut W,
        buf: &'a mut B,
        #[pin]
        _pin: PhantomPinned,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    WriteAllBuf {
        writer,
        buf,
        _pin: PhantomPinned,
    }
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        let me = self.project();

        loop {
            let view = super::write_buf::BufWriteView::from_buf(&**me.buf);
            let remaining = view.remaining();

            if remaining == 0 {
                return Poll::Ready(Ok(()));
            }

            let vectored = me.writer.is_write_vectored();
            let poll_res = if vectored {
                let writable = view.writable();
                let slices = [IoSlice::new(writable)];
                let slice_count = slices.len();
                let mut idx = 0;
                let mut selected: &[u8] = writable;
                let mut found = false;

                while idx < slice_count {
                    let candidate = &slices[idx];
                    let candidate_len = candidate.len();

                    if candidate_len == 0 {
                        idx += 1;
                        continue;
                    }

                    selected = candidate;
                    found = true;
                    break;
                }

                if found {
                    Pin::new(&mut *me.writer).poll_write(cx, selected)
                } else {
                    Pin::new(&mut *me.writer).poll_write(cx, writable)
                }
            } else {
                let chunk = view.writable();
                Pin::new(&mut *me.writer).poll_write(cx, chunk)
            };

            let ready_write = match poll_res {
                Poll::Pending => None,
                Poll::Ready(result) => Some(result),
            };

            match ready_write {
                None => {
                    return Poll::Pending;
                }
                Some(Ok(n)) => {
                    if n == 0 {
                        let err = super::write_all::write_zero_error();
                        return Poll::Ready(Err(err));
                    }

                    let finished_buf = n >= remaining;
                    me.buf.advance(n);
                    let leftover = me.buf.remaining();

                    if finished_buf {
                        if leftover == 0 {
                            return Poll::Ready(Ok(()));
                        }
                    } else if leftover == 0 {
                        return Poll::Ready(Ok(()));
                    }
                }
                Some(Err(err)) => {
                    return Poll::Ready(Err(err));
                }
            }
        }
    }
}

